jq -r 'def col(p): if p >= 90 then "\u001b[31m" elif p >= 70 then "\u001b[33m" else "" end;
def two: tostring | if length < 2 then "0" + . else . end;
def fmt(s): if s <= 0 then "0m"
  elif s >= 86400 then "\(s / 86400 | floor)d\(s % 86400 / 3600 | floor)h"
  else "\(s / 3600 | floor)h\(s % 3600 / 60 | floor | two)m" end;
def seg(l; w): if w.used_percentage == null then empty
  else "\(col(w.used_percentage))\(l) \(w.used_percentage | round)%\u001b[0m \u001b[90m↻\(fmt((w.resets_at // now) - now))\u001b[0m" end;
.rate_limits // {} | [seg("5h"; .five_hour), seg("wk"; .seven_day)] | join(" \u001b[90m·\u001b[0m ")'
